// 各アイテムごとにOCR結果を整形して返す
return items.map(item => {
  const parsed = item.json["ParsedResults"]?.[0];
  let text = parsed?.ParsedText || "";

  // ノイズ除去・整形
  text = text
    .replace(/\r/g, "\n")             // 改行コード統一
    .replace(/\n{2,}/g, "\n")         // 余分な改行を削除
    .replace(/[^\S\n]+/g, " ")        // 不要な空白を削除
    .replace(/　/g, " ")              // 全角スペースを半角に
    .replace(/[“”]/g, '"')            // 変な引用符を統一
    .replace(/[‘’]/g, "'")
    .replace(/[円¥]/g, "円");         // 円記号を統一

  return {
    json: {
      text: text.trim()
    }
  };
});

// 各アイテム（PDFごと）を独立して処理
return items.map(item => {
  const content = item.json.message?.content;

  // JSON構造を安全にパース
  let parsed = {};
  try {
    parsed = typeof content === "string" ? JSON.parse(content) : content;
  } catch (e) {
    parsed = { error: "Invalid JSON", raw: content };
  }

  // 各アイテムとして出力（個別にスプレッドシートに渡る）
  return { json: parsed };
});
